impl Solution{pub fn game_of_life(b:&mut Vec<Vec<i32>>){let(m,n)=(b.len(),b[0].len());for i in 0..m{for j in 0..n{let mut c=0;for a in -1..=1{for z in -1..=1{if a==0&&z==0{continue}let(x,y)=(i as i32+a,j as i32+z);if x>=0&&y>=0&&x<m as i32&&y<n as i32&&(b[x as usize][y as usize]&1)==1{c+=1}}}if(b[i][j]&1)==1&&(c==2||c==3){b[i][j]|=2}else if(b[i][j]&1)==0&&c==3{b[i][j]|=2}}}for r in b{for x in r{*x>>=1}}}}
